// Recovered from the July 20 Deckplate/AI Lantern session (regenerated by transcript replay).
// Integration smoke: boot the whole Lantern suite (with Deckplate spliced in)
// inside jsdom, mount the app, run the session-only import path end to end.
const fs = require('fs');
const path = require('path');
const { JSDOM } = require("jsdom");
const html = fs.readFileSync(require("path").join(__dirname, "..", "src", "lantern.inner.html"), 'utf8');

const dom = new JSDOM(html, { runScripts: 'dangerously', url: 'http://localhost/', pretendToBeVisual: true });
const { window } = dom;
const { document } = window;
window.HTMLMediaElement.prototype.play = function () { this.dispatchEvent(new window.Event('play')); return Promise.resolve(); };
window.HTMLMediaElement.prototype.pause = function () { this.dispatchEvent(new window.Event('pause')); };
window.HTMLMediaElement.prototype.load = function () {};

let fails = 0;
function check(name, cond) { console.log((cond ? 'PASS' : 'FAIL') + '  ' + name); if (!cond) fails++; }
const tick = () => new Promise(r => setTimeout(r, 30));

(async () => {
  document.dispatchEvent(new window.Event('DOMContentLoaded', { bubbles: true }));
  await tick();
  check('shell booted (header bar present)', !!document.querySelector('header.bar'));
  const tiles = [...document.querySelectorAll('.tile .name')].map(n => n.textContent);
  check('Deckplate tile on home screen', tiles.includes('Deckplate'));
  check('existing apps intact (Writer + Smith Bench tiles present)', tiles.includes('Writer') && tiles.length > 30);
  check('guide registered', window.Lantern.guide.has('deckplate'));

  // mount Deckplate via hash routing
  window.location.hash = 'deckplate';
  window.dispatchEvent(new window.Event('hashchange'));
  await tick(); await tick();
  const DP = window.Lantern.DP;
  check('dp-root mounted in workspace', !!document.getElementById('dp-root'));
  check('session-only fallback engaged (no IndexedDB in jsdom)', DP.sessionOnly === true);
  check('empty state -> chooser modal auto-opened', document.getElementById('dp-modal') && document.getElementById('dp-modal').hidden === false);
  DP.closeModal();

  // import a real MP3 fixture through the session store
  const buf = fs.readFileSync(require("path").join(__dirname, "fixtures", "t1.mp3"));
  const file = new window.File([buf], 't1.mp3', { type: 'audio/mpeg' });
  await DP.importFiles([{ file, relPath: null }], {});
  check('track imported into session library', DP.lib.length === 1);
  const rec = DP.lib[0];
  check('tags read (title/artist/albumArtist)', rec.title === 'Na\u00efve Song' && rec.artist === 'Bj\u00f6rk & Crew' && rec.albumArtist === 'Various Artists' && rec.track === 3);
  check('embedded USLT lyrics captured', /hello.*\n.*anybody in there/i.test(rec.lyricsRaw || '') || (rec.lyricsRaw || '').length > 10);
  check('row rendered in Songs view', document.querySelector('.dp-rtitle') && document.querySelector('.dp-rtitle').textContent === 'Na\u00efve Song');

  // play + transport + queue view
  document.querySelector('.dp-hit').click();
  await tick();
  check('transport visible with track', document.getElementById('dp-transport').hidden === false &&
    document.getElementById('dp-nptitle').textContent === 'Na\u00efve Song');
  check('row marked playing', !!document.querySelector('.dp-row.playing'));

  // lyrics panel (unsynced path)
  DP.toggleLyrics();
  check('lyrics panel opens', document.getElementById('dp-lyrpanel').hidden === false);
  check('unsynced label shown', /UNSYNCED/.test(document.getElementById('dp-lyrbody').textContent));
  DP.toggleLyrics();

  // dedupe on re-import
  await DP.importFiles([{ file, relPath: null }], {});
  check('duplicate skipped', DP.lib.length === 1);

  // navigate away: audio keeps state, doc listeners detach, then remount restores
  window.location.hash = 'writer';
  window.dispatchEvent(new window.Event('hashchange'));
  await tick();
  check('writer mounts after deckplate (regression)', !!document.querySelector('.toolbar') && /New document/.test(document.body.textContent));
  check('deckplate unmounted flag', DP.mounted === false);
  check('queue survives unmount', DP.queue.length === 1 && DP.qpos === 0);
  window.location.hash = 'deckplate';
  window.dispatchEvent(new window.Event('hashchange'));
  await tick(); await tick();
  check('remount restores transport from live state', document.getElementById('dp-transport').hidden === false &&
    document.getElementById('dp-nptitle').textContent === 'Na\u00efve Song');

  // sheet -> remove with tombstone semantics (session mode: store no-ops, lib updates)
  document.querySelector('.dp-more').click();
  await tick();
  check('action sheet opens', document.getElementById('dp-sheet').hidden === false);
  document.querySelector('[data-s="rm"]').click();
  await tick();
  document.querySelector('[data-m="yes"]').click();
  await tick(); await tick();
  check('track removed + playback stopped', DP.lib.length === 0 && DP.qpos === -1 &&
    document.getElementById('dp-transport').hidden === true);

  console.log(fails ? 'SMOKE FAILURES: ' + fails : 'ALL SUITE SMOKE TESTS PASS');
  process.exit(fails ? 1 : 0);
})().catch(e => { console.error('SMOKE CRASH', e); process.exit(1); });
